package owl.nh;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.*;
public final class KioskPrivacyTests {
 static void check(boolean yes,String message){CoreTests.check(yes,"Kiosk privacy: "+message);}
 public static void main(String[] args){java.util.List<String> names=Arrays.asList("Turbo");check(KioskText.spans("Turbo: hello TURBO",names).size()==2,"match all case-insensitive name instances");check(KioskText.spans("Turbocharged turbo_123",names).isEmpty(),"do not mask unrelated longer names");check(KioskText.title("Orion - Turbo",names).equals("Orion - \u2588\u2588\u2588\u2588\u2588"),"native title keeps the app name and masks the account");check(KioskText.spans("a+b",Arrays.asList("a+b")).size()==1,"names are literal, never interpreted as regular expressions");Rectangle box=new Rectangle(20,40,200,16);java.util.List<Rectangle> masks=KioskText.masks("<col=ff0000>Turbo</col>: hello",box,0,0,14,t->KioskText.plain(t).length()*6,names);check(masks.size()==1&&masks.get(0).x==20&&masks.get(0).width<=34,"strip covers name without blanking the rest of chat");check(KioskText.masks("nothing private",box,0,0,14,t->t.length()*6,names).isEmpty(),"unrelated text remains visible");
  Map<String,Object> wf=new HashMap<>();wf.put("getText","Turbo: hello");wf.put("getBounds",box);wf.put("isVisible",true);wf.put("getLineHeight",14);net.runelite.api.widgets.Widget w=ChambersTests.fake(net.runelite.api.widgets.Widget.class,wf);Map<String,Object> pf=new HashMap<>();pf.put("getName","Turbo");pf.put("getLogicalHeight",100);pf.put("getCanvasTextLocation",new net.runelite.api.Point(120,120));net.runelite.api.Player player=ChambersTests.fake(net.runelite.api.Player.class,pf);Map<String,Object> cf=new HashMap<>();cf.put("getLocalPlayer",player);cf.put("getUsername","Turbo");cf.put("getWidgetRoots",new net.runelite.api.widgets.Widget[]{w});net.runelite.api.Client client=ChambersTests.fake(net.runelite.api.Client.class,cf);KioskPrivacy privacy=new KioskPrivacy(client);BufferedImage image=new BufferedImage(320,200,BufferedImage.TYPE_INT_RGB);Graphics2D g=image.createGraphics();g.setColor(Color.WHITE);g.fillRect(0,0,320,200);privacy.overlay.render(g);g.dispose();check(image.getRGB(23,45)==Color.BLACK.getRGB(),"chat name is covered by an opaque strip even without a running bot");check(image.getRGB(290,170)==Color.WHITE.getRGB(),"unrelated game pixels remain untouched");check(w.getText().equals("Turbo: hello")&&player.getName().equals("Turbo"),"game identity and widget text remain unchanged");System.out.println("Kiosk privacy checks passed: title, literal names, chat strips, passive idle rendering and untouched game state. Synthetic only.");}
}
